    }
    // Callbacks run outside the lock so writers may take their own locks without lock-order coupling.
    for (const auto &writer : tapWriterSnapshot_) {
        writer->OnTapData(*buffer);
    }
}

int32_t HpaeRendererManager::RegisterSessionEffectTapWriter(uint32_t sessionId,
    const std::weak_ptr<IHpaeInnerCapTapWriter> &writer)
{
    auto request = [this, sessionId, writer]() {
        auto sinkInputNode = SafeGetMap(sinkInputNodeMap_, sessionId);
        CHECK_AND_RETURN_LOG(sinkInputNode != nullptr,
            "session %{public}u not found for tap writer", sessionId);
        auto shared = writer.lock();
        CHECK_AND_RETURN_LOG(shared != nullptr, "tap writer expired, session %{public}u", sessionId);
        sinkInputNode->AddInnerCapTapWriter(shared);
        HpaeProcessorType sceneType = GetConnectedProcessorType(sessionId);
        auto processCluster = SafeGetMap(sceneClusterMap_, sceneType);
        auto seNode = processCluster != nullptr ?
            processCluster->GetSessionEffectNode(sessionId) : nullptr;
        if (seNode != nullptr) {
            seNode->AddTapWriter(writer);
        }
        AUDIO_INFO_LOG("tap writer registered, session %{public}u, se attached %{public}d",
            sessionId, seNode != nullptr);
    };
    SendRequest(std::move(request), __func__);
    return SUCCESS;
}

