void HpaeRendererManager::SeedSessionEffectTapWriters(uint32_t sessionId,
    const std::shared_ptr<HpaeProcessCluster> &processCluster)
{
    auto sinkInputNode = SafeGetMap(sinkInputNodeMap_, sessionId);
    auto seNode = processCluster != nullptr ? processCluster->GetSessionEffectNode(sessionId) : nullptr;
    if (sinkInputNode == nullptr || seNode == nullptr) {
        return;
    }
    // Re-seeding is idempotent: HpaeSessionEffectNode::AddTapWriter ignores duplicates.
    for (const auto &tapWriter : sinkInputNode->GetInnerCapTapWriters()) {
        seNode->AddTapWriter(tapWriter);
    }
}
